class CounterBox {
    private static int instanceCount = 0; // Static field
    private int boxId;                    // Instance field

    static {
        System.out.println("Static block: loaded once");
    }

    public CounterBox() {
        instanceCount++;
        this.boxId = instanceCount;
        System.out.println("Box #" + boxId + " created. Total: " + instanceCount);
    }
}

public class MultipleInstanceDemo {
    public static void main(String[] args) {
        new CounterBox();
        new CounterBox();
        new CounterBox();
    }
}

