class NetworkPacket {
    private String source;
    private String destination;
    private int port;
    private int payloadSize;

    public NetworkPacket(String src, String dest) {
        this(src, dest, 80, 512);
    }

    public NetworkPacket(String src, String dest, int port) {
        this(src, dest, port, 512);
    }

    public NetworkPacket(String src, String dest, int port, int size) {
        this.source = src;
        this.destination = dest;
        this.port = port;
        this.payloadSize = size;
    }

    public String describe() {
        return source + " -> " + destination + ":" + port + " (" + payloadSize + " bytes)";
    }
}

public class PacketApp {
    public static void main(String[] args) {
        NetworkPacket p1 = new NetworkPacket("10.0.0.1", "10.0.0.2");
        NetworkPacket p2 = new NetworkPacket("10.0.0.1", "10.0.0.3", 443);
        System.out.println(p1.describe());
        System.out.println(p2.describe());
    }
}

