practiceProblems.solutionCode:
class User {
    protected String username;
    public User(String username) {
        this.username = username;
    }
}

class SuperUser extends User {
    private int accessLevel;
    public SuperUser(String name, int level) {
        super(name); // Explicit super call satisfies User constructor
        this.accessLevel = level;
    }
    public void display() {
        System.out.println("SuperUser created: " + username + " with access level " + accessLevel);
    }
}

public class UserChainingBug {
    public static void main(String[] args) {
        SuperUser su = new SuperUser("root", 99);
        su.display();
    }
}

class LifecycleEntity {
    public static int staticCount = 0;
    public int instanceCount = 0;

    static {
        staticCount += 10;
    }

    {
        instanceCount += 1;
        staticCount += 1;
    }

    public LifecycleEntity() {
        instanceCount += 5;
    }
}

public class LifecycleApp {
    public static void main(String[] args) {
        LifecycleEntity e1 = new LifecycleEntity();
        LifecycleEntity e2 = new LifecycleEntity();

        System.out.println("Total staticCount: " + LifecycleEntity.staticCount);
        System.out.println("e1 instanceCount: " + e1.instanceCount);
        System.out.println("e2 instanceCount: " + e2.instanceCount);
    }
}
